class Task:
    def __init__(self, T_i, C_i, D_i):
        self.T = T_i
        self.C = C_i
        self.D = D_i
        if not (self.C <= self.D <= self.T):
            raise ValueError("Task parameters invalid: C_i <= D_i <= T_i must hold")

def calculate_task_utilization(task):
    return task.C / task.T

def calculate_system_utilization(task_set):
    U_sys = 0
    for task_i in task_set:
        U_sys += calculate_task_utilization(task_i)
    return U_sys

def calculate_total_interference(task_j, interval_start, interval_end, task_set, m):
    total_interference = 0
    for task_i in task_set:
        if task_i != task_j:
            interference_i_on_j = calculate_interference_from_task(task_i, task_j, interval_start, interval_end)
            total_interference += interference_i_on_j
    return total_interference / m

def calculate_worst_case_single_task_interference(task_i, task_j, task_set, m):
    # First, find J*_j and its interval [r*_j, d*_j)
    r_star_j, d_star_j = find_worst_case_interference_job_interval(task_j, task_set, m)
    # Then, calculate interference of task_i on task_j within that interval
    return calculate_single_task_interference(task_i, task_j, r_star_j, d_star_j)

def classify_job_relative_to_interval(job_release_time, job_deadline, interval_start, interval_end):
    if job_release_time < interval_start and job_deadline > interval_start:
        return "carry-in"
    elif interval_start <= job_release_time and job_deadline <= interval_end:
        return "body"
    elif interval_start <= job_release_time and job_deadline > interval_end:
        return "carry-out"
    else:
        return "other"

def calculate_task_slack(task_j, task_set, m):
    initial_slack = task_j.D - task_j.C
    total_interference_delay = 0
    for task_i in task_set:
        if task_i != task_j:
            interference_i_on_j = calculate_worst_case_single_task_interference(task_i, task_j, task_set, m) # This needs to be the actual bound
            limited_interference = min(interference_i_on_j, task_j.D - task_j.C + 1)
            total_interference_delay += limited_interference
    return initial_slack - (total_interference_delay / m)

def calculate_lower_bound_task_slack_eqdf(task_j, task_set, m, k):
    initial_slack = task_j.D - task_j.C
    total_interference_delay = 0
    for task_i in task_set:
        if task_i != task_j:
            interference_bound = calculate_eqdf_interference_bound(task_i, task_j, task_set, m, k, task_j.D) # This function needs to implement Eq. (11)
            limited_interference = min(interference_bound, task_j.D - task_j.C + 1)
            total_interference_delay += limited_interference
    return initial_slack - (total_interference_delay / m)

def check_lemma_1_schedulability(task_set, m):
    for task_j in task_set:
        for task_i in task_set:
            if task_i != task_j:
                # Note: I_j<-i needs to be the actual worst-case interference bound
                interference_i_on_j = calculate_worst_case_single_task_interference(task_i, task_j, task_set, m) # Placeholder
                max_tolerable_delay = task_j.D - task_j.C + 1
                limited_interference = min(interference_i_on_j, max_tolerable_delay)
                total_processor_slack = m * max_tolerable_delay
                if limited_interference >= total_processor_slack:
                    return False # Task set is not schedulable
    return True # Task set is schedulable

def check_theorem_1_schedulability(task_set, m, k):
    for task_j in task_set:
        for task_i in task_set:
            if task_i != task_j:
                interference_bound = calculate_eqdf_interference_bound(task_i, task_j, task_j.D, k) # Implements Eq. (11)
                max_tolerable_delay = task_j.D - task_j.C + 1
                limited_interference = min(interference_bound, max_tolerable_delay)
                total_processor_slack = m * max_tolerable_delay
                if limited_interference >= total_processor_slack:
                    return False # Task set is not schedulable for this k
    return True # Task set is schedulable for this k
